export function evaluate({ inputs, time, seed, state }) {
  const g = 9.8;
  const u = inputs.launchSpeed;
  const t = time; // seconds since launch
  // kinematics
  const v = u - g * t; // velocity (m/s)
  const h = u * t - 0.5 * g * t * t; // height above launch (m)
  // limits for display
  const maxU = 5;
  const maxHeight = maxU * maxU / (2 * g); // approx 1.276 m
  const axisX = 80; // left margin
  const axisY = 20; // top margin
  const axisLength = 300; // pixels for full height
  const scale = axisLength / maxHeight;
  const ballX = axisX + 60; // fixed horizontal position
  const ballY = axisY + axisLength - h * scale; // y down
  // motion state label
  let motionState;
  if (Math.abs(v) < 1e-6) {
    motionState = "Still for an instant";
  } else if (v > 0) {
    motionState = "Moving up";
  } else {
    motionState = "Moving down";
  }
  const gravityState = "Gravity pulls down";
  // objects
  const objects = [];
  // y‑axis
  objects.push(...sdk.axis("axis.y", { x: axisX, y: axisY, length: axisLength, orientation: "y", min: 0, max: maxHeight, ticks: [0, maxHeight / 2, maxHeight], label: "Height (m)", unit: "m" }));
  // ball
  objects.push(sdk.circle("ball.toss", ballX, ballY, 24, { text: "" }));
  // motion arrow (velocity) – only if not zero
  if (Math.abs(v) > 1e-6) {
    const dir = v > 0 ? "up" : "down";
    objects.push(sdk.vector("vec.v", { x: ballX, y: ballY }, { value: Math.abs(v), direction: dir, label: "v", scale: 10 }));
  }
  // gravity arrow – constant
  objects.push(sdk.vector("vec.a", { x: ballX, y: ballY }, { value: g, direction: "down", label: "a", scale: 10 }));
  // callout beside ball
  objects.push(...sdk.callout(ballX + 30, ballY - 20, [motionState, gravityState], { id: "callout.toss" }));
  // frame
  const frame = sdk.frame(objects, {});
  // readouts
  const readouts = [
    { id: "motionState", value: motionState },
    { id: "gravityState", value: gravityState }
  ];
  // quantities (for completeness)
  const quantities = {
    launchSpeed: u,
    gravity: g,
    apexTime: u / g,
    apexHeight: u * u / (2 * g),
    velocity: v,
    height: h
  };
  return { frame, readouts, quantities };
}
